/* BINDTOOL_HEADER_FILE(codec_decoder.h)                                           */
/* BINDTOOL_HEADER_FILE_HASH(0)                                                    */

#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

namespace py = pybind11;

#include <gnuradio/aff3ct/codec_decoder.h>

void bind_codec_decoder(py::module& m)
{
    using codec_decoder = ::gr::aff3ct::codec_decoder;

    py::class_<codec_decoder, gr::fec::generic_decoder, std::shared_ptr<codec_decoder>>(
        m,
        "codec_decoder",
        py::multiple_inheritance(), // generic_decoder is a virtual base: pointers must be adjusted
        "Decoder of any AFF3CT code, described by its AFF3CT command line.")
        .def_static("make",
                    &codec_decoder::make,
                    py::arg("aff3ct_args"),
                    py::arg("llr_scale") = 1.0f)
        .def("frames", &codec_decoder::frames)
        .def("info_bits", &codec_decoder::info_bits)
        .def("coded_bits", &codec_decoder::coded_bits);
}
